● Shared scanning backend: real disposable Mongo transactions and HTTP › distinguishes unknown, exact case/space differences, wrong product, wrong state and unavailable assignment

  expect(received).toBe(expected) // Object.is equality

  Expected: "UNKNOWN_BARCODE"
  Received: "VALIDATED"

    100 |   it('distinguishes unknown, exact case/space differences, wrong product, wrong state and unavailable assignment', async () => {
    101 |     expect((await validate({ identifier: 'unknown' })).code).toBe('UNKNOWN_BARCODE');
  > 102 |     expect((await validate({ identifier: unit.barcode.toLowerCase() })).code).toBe('UNKNOWN_BARCODE');
        |                                                                               ^
    103 |     expect((await validate({ identifier: ' ' + unit.barcode })).code).toBe('UNKNOWN_BARCODE');
    104 |     expect((await validate({ productId: key() })).code).toBe('WRONG_PRODUCT');
    105 |     expect((await validate({ intent: 'inspect', productId })).code).toBe('INVALID_UNIT_STATE');

